const body = $input.first().json.body || {};
const day = String(body.day || 'today').toLowerCase();

const start = new Date();
if (day.includes('tomorrow')) start.setDate(start.getDate() + 1);
else if (day.includes('yesterday')) start.setDate(start.getDate() - 1);
start.setHours(0, 0, 0, 0);

const end = new Date(start);
end.setDate(end.getDate() + 1);

return [{ json: { day, timeMin: start.toISOString(), timeMax: end.toISOString() } }];

const day = $('Day range').first().json.day;

const events = $input.all()
  .filter(i => i.json && (i.json.summary || i.json.start))
  .map(i => {
    const e = i.json;
    const startsAt = e.start?.dateTime || e.start?.date;
    const when = e.start?.dateTime
      ? new Date(e.start.dateTime).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
      : 'all day';
    return `${when} ${e.summary || '(untitled)'}`;
  });

return [{ json: { day, count: events.length, events } }];
